  bool has(String key) => _strings.containsKey(key);

  /// 대사 풀 — `{base}_1`, `{base}_2`, … 중 존재하는 키에서 하나를 무작위로.
  /// (2026-09-16 대표님) 승패·인사 대사는 목록으로 두고 랜덤. 목록은 엑셀 대본에서 늘릴 수 있다.
  String pick(String base, Random rng, [List<String>? args]) {
    final keys = <String>[];
    for (int i = 1; i <= 30; i++) {
      final k = '${base}_$i';
      if (!has(k)) break;
      keys.add(k);
    }
    if (keys.isEmpty) return get(base, args);
    return get(keys[rng.nextInt(keys.length)], args);
  }

  /// 풀의 키 하나를 무작위로 (화면은 키를 저장했다가 언어 바뀌면 다시 해석하므로)
  String pickKey(String base, Random rng) {
    final keys = <String>[];
    for (int i = 1; i <= 30; i++) {
      final k = '${base}_$i';
      if (!has(k)) break;
      keys.add(k);
    }
    return keys.isEmpty ? base : keys[rng.nextInt(keys.length)];
  }

  String get(String key, [List<String>? args]) {
    final map = _strings[key];
    if (map == null) return key;
    String text = map[locale] ?? map['en'] ?? key;
    if (args != null) {
      for (int i = 0; i < args.length; i++) {
        text = text.replaceAll('{$i}', args[i]);
      }
    }
    return text;
  }

